import string

def generate_names():
    names = set()
    for _ in range(100):
        name = ''.join(random.choices(string.ascii_letters + string.digits, k=6))
        if not any(name.startswith(prefix) or name.endswith(suffix) for prefix in ['Mr.', 'Mrs.', 'Ms.'] for suffix in ['.', ','] for name in names)
            names.add(name.capitalize())
    return sorted(names)

if __name__ == '__main__':
    print(generate_names())

